{
  "references": [
    {
      "id": "R1",
      "summary_ko": "핏불처럼 보이지 않으며 눈의 움직임이 부드럽지 않음."
    },
    {
      "id": "R2",
      "summary_ko": "개의 꼬리가 지나치게 빠르게 흔들리며 부자연스러워 보임."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "영상 특징과 픽셀 구조 변화에 따른 형태 및 존재 변화 가능성 제안."
    },
    {
      "id": "C2",
      "summary_ko": "개의 꼬리가 흔들리는 동안 빠르게 형태가 변하고 부자연스럽게 깜빡임."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 구체적인 대상이나 현상이 명시되지 않은 일반적인 측정 가설이므로 R1과 동일한 결함인지 명확히 알 수 없습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 개의 외모 및 눈 움직임의 이상을 다루는 반면, C2는 개의 꼬리 형태 변화 및 깜빡임을 다룹니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 대상이 특정되지 않은 포괄적 측정 가설로, 꼬리의 부자연스러운 흔들림을 언급한 R2와 일치하는지 단정할 수 없습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "same",
      "reason_ko": "두 설명 모두 개 꼬리가 흔들릴 때 발생하는 부자연스러운 움직임 및 형태 이상 현상을 가리키고 있습니다."
    }
  ]
}
